CREATE TABLE app_grants(id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES apps(id) ON DELETE CASCADE, org_id TEXT NOT NULL REFERENCES organizations(id), kind TEXT NOT NULL CHECK(kind IN ('saga', 'table', 'file')), ref TEXT NOT NULL CHECK(length(ref) BETWEEN 1 AND 128), permission TEXT NOT NULL CHECK(permission IN ('invoke', 'read', 'write')), revoked INTEGER NOT NULL DEFAULT 0 CHECK(revoked IN (0, 1)), created_at TEXT NOT NULL, UNIQUE(app_id, kind, ref, permission));
CREATE INDEX app_grants_app ON app_grants(app_id, revoked);
CREATE TABLE app_tables(id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES apps(id) ON DELETE CASCADE, org_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 64), visibility TEXT NOT NULL DEFAULT 'visible' CHECK(visibility IN ('visible', 'hidden')), columns_json TEXT NOT NULL DEFAULT '[]' CHECK(length(columns_json) <= 2048), revision INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(app_id, name));
CREATE INDEX app_tables_app ON app_tables(app_id);
CREATE TABLE app_rows(id TEXT PRIMARY KEY, table_id TEXT NOT NULL REFERENCES app_tables(id) ON DELETE CASCADE, app_id TEXT NOT NULL REFERENCES apps(id) ON DELETE CASCADE, org_id TEXT NOT NULL REFERENCES organizations(id), data_json TEXT NOT NULL CHECK(length(data_json) <= 4096), table_revision INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX app_rows_table ON app_rows(table_id, table_revision DESC, id DESC);
CREATE TABLE app_files(id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES apps(id) ON DELETE CASCADE, org_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 128), content_type TEXT NOT NULL DEFAULT 'application/octet-stream' CHECK(length(content_type) BETWEEN 1 AND 128), size INTEGER NOT NULL DEFAULT 0 CHECK(size BETWEEN 0 AND 32768), sha256 TEXT NOT NULL DEFAULT '' CHECK(length(sha256) <= 64), content_base64 TEXT NOT NULL DEFAULT '' CHECK(length(content_base64) <= 43696), version INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'ready')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(app_id, name));
CREATE INDEX app_files_app ON app_files(app_id);
CREATE TABLE app_file_tokens(token_hash TEXT PRIMARY KEY, file_id TEXT NOT NULL REFERENCES app_files(id) ON DELETE CASCADE, app_id TEXT NOT NULL REFERENCES apps(id) ON DELETE CASCADE, scope TEXT NOT NULL CHECK(scope IN ('upload', 'download')), expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE app_executions(app_id TEXT NOT NULL REFERENCES apps(id) ON DELETE CASCADE, execution_id TEXT NOT NULL, org_id TEXT NOT NULL REFERENCES organizations(id), saga_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(app_id, execution_id));
CREATE INDEX app_executions_exec ON app_executions(execution_id);
